  margin: 10px auto;
  padding: 9px 16px;
  border: 0;
  background: #101828;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.report {
  width: 210mm;
  min-height: 297mm;
  margin: 0 auto;
  background: white;
  padding: 13mm;
  box-sizing: border-box;
  box-shadow: 0 14px 40px rgba(15, 23, 42, 0.16);
}

.top-line {
  height: 7px;
  margin: -13mm -13mm 13mm;
  background: linear-gradient(90deg, #101828, #0f766e, #2563eb);
}

.hero,
.brand,
.panel-head,
.footer-grid {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.hero {
  border-bottom: 1px solid #d0d5dd;
  padding-bottom: 14px;
}

.brand {
  justify-content: flex-start;
  align-items: flex-start;
}

.logo {
  width: 86px;
  max-height: 68px;
  object-fit: contain;
  display: none;
}

.logo-fallback {
  width: 78px;
  height: 62px;
  background: #101828;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 900;
}

.company-name {
  font-size: 24px;
  font-weight: 900;
}

.company-meta {
  margin-top: 6px;
  color: #667085;
  font-size: 12px;
  line-height: 1.45;
}

.title-card {
  text-align: right;
}

.badge {
  display: inline-block;
  padding: 6px 10px;
  background: #ecfdf5;
  color: #0f766e;
  border: 1px solid #99f6e4;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

h1 {
  margin: 9px 0 4px;
  font-size: 29px;
}

.doc-no {
  font-size: 17px;
  font-weight: 900;
}

.status {
  display: inline-block;
  margin-top: 7px;
  padding: 5px 9px;
  border: 1px solid #d0d5dd;
  font-size: 12px;
  font-weight: 800;
}

.info-strip,
.kpi-grid {
  display: grid;
  gap: 10px;
  margin: 15px 0;
}

.info-strip {
  grid-template-columns: 1.2fr 1fr 1fr 1fr;
}

.info-strip div,
.kpi,
.panel,
.notes {
  border: 1px solid #d0d5dd;
}

.info-strip div,
.kpi {
  padding: 10px;
}

span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  margin-bottom: 5px;
  font-weight: 700;
}

.kpi-grid {
  grid-template-columns: repeat(7, 1fr);
}

.kpi b {
  font-size: 18px;
}

.kpi.danger b {
  color: #dc2626;
}

.kpi.warn b {
  color: #d97706;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
}

.panel-head {
  align-items: center;
  background: #101828;
  color: white;
  padding: 9px 10px;
}

.panel-head h2 {
  margin: 0;
  font-size: 14px;
}

.panel-head span {
  color: #d0d5dd;
  margin: 0;
