th {
  background: #f2f4f7;
  color: #344054;
  font-size: 10px;
  text-align: left;
  padding: 7px;
}

td {
  border-top: 1px solid #eaecf0;
  padding: 7px;
  font-size: 11px;
  vertical-align: top;
}

.product-code,
.strong {
  font-weight: 900;
}

.sub {
  color: #667085;
  font-size: 10px;
  margin-top: 2px;
