.right {
  text-align: right;
  white-space: nowrap;
}

.footer-grid {
  margin-top: 16px;
  align-items: flex-start;
}

.qr-box {
  width: 130px;
  text-align: center;
}

.qr {
  width: 112px;
  height: 112px;
  image-rendering: pixelated;
}

.qr-box div {
  color: #667085;
  font-size: 10px;
  margin-top: 4px;
}

.notes {
  flex: 1;
  padding: 12px;
  color: #475467;
  font-size: 12px;
  line-height: 1.45;
