function val(value) {
  return String(value ?? "");
}
function money(value) {
  return Number(value || 0).toFixed(2);
}
function qty(value) {
  return Number(value || 0).toFixed(3);
}
function initials(name) {
  return val(name || "AX").split(" ").filter(Boolean).slice(0, 2).map(x => x[0]).join("").toUpperCase();
}
function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.innerText = val(value);
}
function emptyRow(colspan, text) {
  return `<tr><td colspan="${colspan}" class="sub">${val(text || "No data")}</td></tr>`;
}
function productCell(row) {
  return `
    <div class="product-code">${val(row.productCode)}</div>
    <div class="sub">${val(row.productName)}${row.barcode ? " | " + val(row.barcode) : ""}</div>
  `;
}
function qrPayload(header, summary) {
  return ["TYPE=WAREHOUSE_REPORT", "WAREHOUSE=" + val(header.warehouseCode), "FROM=" + val(header.dateFrom), "TO=" + val(header.dateTo), "PRODUCTS=" + val(summary.productCount), "VALUE=" + val(summary.totalValue)].join("&");
}
function qrSrc(payload) {
  return "https://api.qrserver.com/v1/create-qr-code/?size=140x140&ecc=M&margin=1&data=" + encodeURIComponent(payload);
}
function render(model) {
  const h = model.header || {};
  const s = model.summary || {};
  const lowStock = model.lowStock || [];
  const topValue = model.topValue || [];
  const expiry = model.expiry || [];
  const inTransit = model.inTransit || [];
  const tasks = model.tasks || [];
  const slowStock = model.slowStock || [];
  const companyDisplay = h.companyName || "";
  setText("companyName", companyDisplay || "Company");
  setText("companyMeta", [h.companyAddress, h.companyPostalCode, h.companyCity, h.companyTaxNumber ? "Tax No: " + h.companyTaxNumber : "", h.companyEmail, h.companyPhone].filter(Boolean).join(" | "));
  const logo = document.getElementById("logo");
  const fallback = document.getElementById("logoFallback");
  if (h.companyLogoPath) {
    logo.src = h.companyLogoPath;
    logo.style.display = "block";
    fallback.style.display = "none";
  } else {
    logo.style.display = "none";
    fallback.style.display = "flex";
    fallback.innerText = initials(companyDisplay);
  }
  setText("warehouseName", `${h.warehouseCode || ""} - ${h.warehouseName || ""}`);
  setText("printedAt", h.printedAt || "");
  setText("warehouse", `${h.warehouseCode || ""} - ${h.warehouseName || ""}`);
  setText("period", `${h.dateFrom || ""} - ${h.dateTo || ""}`);
  setText("printedBy", h.printedBy || "");
  setText("reportRef", `${h.warehouseCode || "ALL"}-${h.dateFrom || ""}-${h.dateTo || ""}`);
  setText("productCount", s.productCount || 0);
  setText("totalQuantity", qty(s.totalQuantity));
  setText("totalValue", money(s.totalValue));
  setText("outOfStock", s.outOfStockCount || 0);
  setText("lowStockCount", s.lowStockCount || 0);
  setText("openTasks", s.openTaskCount || 0);
  setText("openTransfers", s.openTransferCount || 0);
  setText("lowStockCountRows", `${lowStock.length} rows`);
  document.getElementById("lowStockBody").innerHTML = lowStock.length ? lowStock.map(row => `
      <tr>
        <td>${productCell(row)}</td>
        <td class="right">${qty(row.currentStock)}</td>
        <td class="right">${qty(row.minimumStock)}</td>
        <td>${val(row.warehouseCode)}</td>
      </tr>
    `).join("") : emptyRow(4);
  setText("topValueCountRows", `${topValue.length} rows`);
  document.getElementById("topValueBody").innerHTML = topValue.length ? topValue.map(row => `
      <tr>
        <td>${productCell(row)}</td>
        <td class="right">${qty(row.currentStock)}</td>
        <td class="right">${money(row.stockValue)}</td>
      </tr>
    `).join("") : emptyRow(3);
  setText("expiryCountRows", `${expiry.length} rows`);
  document.getElementById("expiryBody").innerHTML = expiry.length ? expiry.map(row => `
      <tr>
        <td>${productCell(row)}</td>
        <td>${val(row.batchNumber || row.serialNumber)}</td>
        <td>${val(row.expiryDate)}<div class="sub">${val(row.daysToExpiry)} days</div></td>
        <td class="right">${qty(row.batchStock)}</td>
      </tr>
    `).join("") : emptyRow(4);
  setText("transitCountRows", `${inTransit.length} rows`);
  document.getElementById("transitBody").innerHTML = inTransit.length ? inTransit.map(row => `
      <tr>
        <td>
          <div class="strong">${val(row.transferNumber)}</div>
          <div class="sub">${val(row.status)}</div>
        </td>
        <td>${val(row.sourceWarehouseCode)} → ${val(row.destinationWarehouseCode)}</td>
        <td class="right">${qty(row.totalQuantity)}</td>
      </tr>
    `).join("") : emptyRow(3);
  setText("taskCountRows", `${tasks.length} rows`);
  document.getElementById("tasksBody").innerHTML = tasks.length ? tasks.map(row => `
      <tr>
        <td>
          <div class="strong">${val(row.taskNumber)}</div>
          <div class="sub">${val(row.documentNumber)}</div>
        </td>
        <td>${val(row.taskType)}</td>
        <td>${val(row.status)}</td>
        <td>${val(row.priority)}</td>
      </tr>
    `).join("") : emptyRow(4);
  setText("slowCountRows", `${slowStock.length} rows`);
  document.getElementById("slowBody").innerHTML = slowStock.length ? slowStock.map(row => `
      <tr>
        <td>${productCell(row)}</td>
        <td class="right">${qty(row.currentStock)}</td>
        <td class="right">${val(row.daysWithoutMovement)}</td>
      </tr>
    `).join("") : emptyRow(3);
  const payload = qrPayload(h, s);
  document.getElementById("qr").src = qrSrc(payload);
  setText("qrText", `${h.warehouseCode || "ALL"} report`);
  document.getElementById("printBtn").onclick = () => window.print();
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

